     */
    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = UsuarioPeer::USUARIO_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(UsuarioPeer::USUARIO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . UsuarioPeer::USUARIO_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(UsuarioPeer::USUARIO_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setUsuarioId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
    }

